oxy_webhelp_navlinks = {"tocId-d39307e43633":{"topics":[{"title":"Adding an Atlassian Confluence site","shortdesc":"<p class=\"shortdesc\">Add an Atlassian Confluence site to <span class=\"ph\">RSC<\/span> to back up your Confluence         spaces and restore pages and attachments.<\/p>","href":"confluence\/confluence_adding_site.html","attributes":{"data-id":"confluence_adding_site"},"menu":{"hasChildren":false},"tocID":"confluence_adding_site-d39307e43634","topics":[]},{"title":"Protecting Atlassian Confluence with SLA Domains","shortdesc":"<p class=\"shortdesc\">You can protect Atlassian Confluence data by assigning an SLA Domain to the Atlassian         site. The SLA Domain defines how often <span class=\"ph\">RSC<\/span> takes snapshots and how long it         retains them.<\/p>","href":"confluence\/confluence_protection_sla_domain.html","attributes":{"data-id":"confluence_protection_sla_domain"},"menu":{"hasChildren":false},"tocID":"confluence_protection_sla_domain-d39307e43648","topics":[]},{"title":"Creating an SLA Domain for SaaS applications","shortdesc":"<p class=\"shortdesc\">Create an SLA Domain with custom backup frequency and retention policies to retain         snapshot data beyond a year.<\/p>","href":"common\/saas_creating_sla_domains.html","attributes":{"data-id":"saas_creating_sla_domains"},"menu":{"hasChildren":false},"tocID":"saas_creating_sla_domains-d39307e43662","topics":[]}]}};